    if not words:
        return ""

    # Drop a trailing "id" suffix (e.g. "author_id" -> "Author")
    if len(words) >= 2 and words[-1] == "id":
        words = words[:-1]
    if not words:
        words = ["id"]

    def _format_word(word: str, capitalize: bool = False) -> str:
        if word in _ACRONYMS:
            return word.upper()
        if capitalize:
            return word.capitalize()
        return word

    return " ".join(
        _format_word(w, capitalize=(i == 0))
        for i, w in enumerate(words)
    )
